if(typeof globalThis.navIcon!=='function')globalThis.navIcon=function(id,f){return f};
/* Local preview workflows. Server authorization and shared storage remain required. */
db.branches??=[...new Set(db.staff.map(s=>s.branch))].map(name=>({name,lat:null,lng:null}));db.punches??=[];db.audit??=[];db.adjustments??=[];db.attendanceOpening??=[];db.archived??=[];db.branchPermissions??={};db.seenRequests??=[];
navs.push(['locations','⌖','مواقع الفروع'],['records','≡','سجل الحضور الفعلي'],['audit','↺','سجل التعديلات'],['archive','▥','أرشيف الموظفين']);
const baseRender=render;let selectedEmployee=db.staff[0]?.id,geoBusy=false;
function audit(action){db.audit.push({at:new Date().toISOString(),action,actor:role});save()}
function cairoDay(t=Date.now()){return new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Cairo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(t))}
function distanceMeters(a,b){const rad=n=>n*Math.PI/180;const x=Math.sin(rad(b.lat-a.lat)/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(rad(b.lng-a.lng)/2)**2;return 6371000*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x))}
function geoDecision(branch,coords){if(!branch||branch.lat===null||branch.lng===null)return {ok:false,message:'موقع الفرع غير محدد. الإدارة لازم تضبطه الأول.'};if(!Number.isFinite(coords.latitude)||!Number.isFinite(coords.longitude)||!Number.isFinite(coords.accuracy)||coords.accuracy<0)return {ok:false,message:'قراءة الموقع غير صالحة؛ حاول تاني.'};const distance=distanceMeters({lat:branch.lat,lng:branch.lng},{lat:coords.latitude,lng:coords.longitude});if(coords.accuracy>30)return {ok:false,distance,message:'دقة الموقع ضعيفة. افتح GPS الدقيق وحاول من مكان مفتوح؛ المطلوب دقة ٣٠ متر أو أفضل.'};return {ok:distance+coords.accuracy<=80,distance,message:distance+coords.accuracy<=80?'تم التحقق من موقعك':`التسجيل مرفوض: المسافة ${Math.ceil(distance)} متر، ودقة الموقع ±${Math.ceil(coords.accuracy)} متر. لازم نطاق الدقة بالكامل يبقى داخل ٨٠ متر.`}}
function currentEmployee(){return db.staff.find(s=>s.id===Number(selectedEmployee))||db.staff[0]}
function employeePanel(){const s=currentEmployee();if(!s)return '<div class="empty">أضف موظف أولًا</div>';const open=db.punches.find(p=>p.employeeId===s.id&&!p.out);return `<div class="notice" data-preview-only>معاينة محلية: اختيار الموظف هنا للاختبار فقط، وليس تسجيل دخول آمن. السجلات لا تنتقل بين أجهزة الموظفين والإدارة.</div>${card('الحضور بالموقع — نطاق ثابت ٨٠ متر',`<div class="toolbar"><select id="employeeSelect">${db.staff.map(e=>`<option value="${e.id}" ${e.id===s.id?'selected':''}>${esc(e.name)}</option>`).join('')}</select></div><div class="employee-hero"><h2>${esc(s.name)}</h2><p>${esc(s.branch)} • ${open?'وردية مفتوحة':'لا توجد وردية مفتوحة'}</p><button id="geoPunch" class="primary" ${geoBusy?'disabled':''}>${geoBusy?'جارٍ التحقق من الموقع…':open?'تسجيل الانصراف بالموقع':'تسجيل الحضور بالموقع'}</button><p id="geoStatus" role="status">يتطلب إذن الموقع الدقيق. التسجيل متاح داخل الفرع فقط، بدون إرسال طلب موافقة.</p><small>لن نضيف هامش GPS خارج حد الـ٨٠ متر؛ عند ضعف الدقة يطلب إعادة المحاولة.</small></div>`)}${card('طلباتي',db.requests.filter(r=>r.name===s.name).map(r=>`<div class="request"><div class="details"><strong>${esc(r.type)}</strong><p>${esc(r.detail)}</p></div>${badge(r.status)}</div>`).join('')||'<p class="empty">لا توجد طلبات</p>','<button id="myRequest">＋ طلب استثنائي</button>')}`}
function punch(){if(geoBusy)return;const s=currentEmployee(),branch=db.branches.find(b=>b.name===s.branch);if(!branch||branch.lat===null||branch.lng===null)return toast('موقع فرع الموظف غير محدد؛ اضبطه من مواقع الفروع');if(!navigator.geolocation)return toast('المتصفح لا يدعم تحديد الموقع');geoBusy=true;render();navigator.geolocation.getCurrentPosition(pos=>{geoBusy=false;const result=geoDecision(branch,pos.coords);if(Date.now()-pos.timestamp>30000){render();return toast('قراءة الموقع قديمة. أعد المحاولة')}if(!result.ok){render();$('#geoStatus').textContent=result.message;return}const now=new Date().toISOString(),open=db.punches.find(p=>p.employeeId===s.id&&!p.out);const measurement={distance:Math.round(result.distance),accuracy:Math.ceil(pos.coords.accuracy)};if(open){open.out=now;open.outLocation=measurement}else{if(db.punches.some(p=>p.employeeId===s.id&&cairoDay(p.in)===cairoDay(now))){render();return toast('تم تسجيل وردية لهذا الموظف اليوم بالفعل')}db.punches.push({id:Date.now(),employeeId:s.id,name:s.name,branch:s.branch,in:now,out:null,inLocation:measurement})}audit(`${open?'انصراف':'حضور'} بالموقع: ${s.name}`);render();toast('تم التسجيل بعد التحقق من نطاق ٨٠ متر')},err=>{geoBusy=false;render();$('#geoStatus').textContent=err.code===1?'اسمح باستخدام الموقع الدقيق من إعدادات المتصفح. لم يتم تسجيل حضور.':err.code===2?'تعذر تحديد الموقع. شغّل GPS وحاول مرة أخرى.':'انتهت مهلة تحديد الموقع. حاول من مكان مفتوح.'},{enableHighAccuracy:true,maximumAge:0,timeout:20000})}
render=function(){if(!navs.some(n=>n[0]===page))page='overview';baseRender();if(role==='الموظف'){$('#app').innerHTML=employeePanel();$('#employeeSelect')?.addEventListener('change',e=>{selectedEmployee=Number(e.target.value);render()});$('#geoPunch')?.addEventListener('click',punch);$('#myRequest')?.addEventListener('click',()=>requestForEmployee());$('#add').onclick=requestForEmployee;return}
const pending=db.requests.filter(r=>r.status==='معلق');if(pending.length&&page!=='requests')$('#app').insertAdjacentHTML('afterbegin',`<div class="notice"><b>● ${pending.length} طلبات مستنية مراجعتك</b> — تظهر هنا لحد ما تقبلها أو ترفضها. <button id="pendingGo">افتح الطلبات ←</button></div>`);$('#pendingGo')?.addEventListener('click',()=>{page='requests';render()});
if(page==='locations'){$('#app').innerHTML='<div class="notice">لا يوجد موقع افتراضي لأي فرع. حدّد نقطة حقيقية لكل فرع قبل التسجيل. نطاق السماح ثابت ٨٠ متر للحضور والانصراف.</div>'+db.branches.map((b,i)=>card(esc(b.name),`<div class="toolbar" style="flex-wrap:wrap"><p>${b.lat===null?'الموقع لم يتم ضبطه':`Latitude: ${b.lat} • Longitude: ${b.lng}`}</p><button data-coordinates="${i}" class="primary">ضبط الإحداثيات</button><button data-here="${i}">استخدم موقعي الحالي</button>${b.lat!==null?`<a target="_blank" rel="noopener" href="https://www.google.com/maps?q=${b.lat},${b.lng}">عرض على الخريطة ↗</a>`:''}</div>`)).join('');document.querySelectorAll('[data-coordinates]').forEach(b=>b.onclick=()=>branchForm(Number(b.dataset.coordinates)));document.querySelectorAll('[data-here]').forEach(b=>b.onclick=()=>locateBranch(Number(b.dataset.here)))}
if(page==='records')$('#app').innerHTML=hoursReviewBlock()+card('السجلات المتحققة بالموقع — توقيت القاهرة',`<div class="table-wrap"><table><tr><th>الموظف</th><th>الفرع</th><th>الحضور</th><th>الانصراف</th><th>الساعات</th><th>المسافة / الدقة</th></tr>${db.punches.filter(p=>$('#branch').value==='كل الفروع'||p.branch===$('#branch').value).slice().reverse().map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(p.branch)}</td><td>${stamp(p.in)}</td><td>${p.out?stamp(p.out):'وردية مفتوحة'}</td><td>${p.out?((new Date(p.out)-new Date(p.in))/36e5).toFixed(2):'—'}</td><td>${p.inLocation.distance}م / ±${p.inLocation.accuracy}م</td></tr>`).join('')}</table></div>${db.punches.length?'':'<p class="empty">لا توجد سجلات GPS حتى الآن</p>'}`);
if(page==='audit')$('#app').innerHTML=card('سجل العمليات المحلي',db.audit.slice().reverse().map(x=>`<div class="activity"><span>${stamp(x.at)}</span><p>${esc(x.action)}</p></div>`).join('')||'<p class="empty">لا توجد عمليات مسجلة</p>');
if(page==='archive'){$('#app').innerHTML=card('الموظفون المؤرشفون',db.archived.map(s=>`<div class="request"><div class="details">${esc(s.name)}<p>${esc(s.branch)}</p></div><button data-restore="${s.id}">استرجاع</button></div>`).join('')||'<p class="empty">الأرشيف فارغ</p>');document.querySelectorAll('[data-restore]').forEach(b=>b.onclick=()=>{let s=db.archived.find(s=>s.id==b.dataset.restore);db.staff.push(s);db.archived=db.archived.filter(x=>x.id!==s.id);audit('استرجاع الموظف '+s.name);render()})}
if(page==='staff'){$('#app').insertAdjacentHTML('beforeend',card('إدارة الموظفين','<div class="toolbar"><select id="staffAction">'+db.staff.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')+'</select><button id="editStaff">تعديل البيانات</button><button id="archiveStaff">أرشفة الموظف</button></div>'));$('#editStaff').onclick=editEmployee;$('#archiveStaff').onclick=()=>{let s=db.staff.find(s=>s.id==$('#staffAction').value);if(db.punches.some(p=>p.employeeId===s.id&&!p.out))return toast('سجل انصراف الموظف قبل الأرشفة');if(!confirm('أرشفة '+s.name+'؟ السجلات محفوظة ويمكن استرجاع الموظف.'))return;db.archived.push(s);db.staff=db.staff.filter(x=>x.id!==s.id);audit('أرشفة الموظف '+s.name);render()}}
if(page==='payroll'){$('#app').insertAdjacentHTML('beforeend',card('الإضافات والخصومات — مسودة محلية',`<div class="toolbar"><button id="adjustSalary">＋ إضافة / خصم</button></div><div class="table-wrap"><table><tr><th>الموظف</th><th>الأساسي</th><th>صافي المسودة</th></tr>${list().map(s=>`<tr><td>${esc(s.name)}</td><td>${s.salary}</td><td>${s.salary+db.adjustments.filter(a=>a.id===s.id).reduce((sum,a)=>sum+a.amount,0)} ج.م</td></tr>`).join('')}</table></div><p style="padding:16px">الإضافات والخصومات يدوية، ليست صرفًا فعليًا أو احتسابًا تلقائيًا للغياب.</p>`));$('#adjustSalary').onclick=()=>openForm('إضافة أو خصم',options('الموظف','name',db.staff.map(s=>s.name))+options('نوع الحركة','type',['إضافة','خصم'])+field('القيمة','amount','number')+field('السبب','reason'),f=>{const s=db.staff.find(s=>s.name===f.get('name'));db.adjustments.push({id:s.id,amount:Number(f.get('amount'))*(f.get('type')==='خصم'?-1:1),reason:f.get('reason'),at:new Date().toISOString()});audit('تعديل مستحقات '+s.name)})}
if(page==='permissions'){const sel=$('#permissionBranch');const sync=()=>{document.querySelectorAll('[data-permission]').forEach(c=>c.checked=!!db.branchPermissions[sel.value]?.[c.dataset.permission])};sel.onchange=sync;sync();$('#savePermissions').onclick=()=>{db.branchPermissions[sel.value]=Object.fromEntries([...document.querySelectorAll('[data-permission]')].map(c=>[c.dataset.permission,c.checked]));audit('تعديل إعدادات صلاحيات '+sel.value);toast('تم حفظ إعدادات الفرع التجريبية')}}
$('#bell').onclick=()=>{page='requests';render()};const oldForm=$('#form').onsubmit;
};
function stamp(t){return new Date(t).toLocaleString('ar-EG',{timeZone:'Africa/Cairo',dateStyle:'short',timeStyle:'short'})}
function branchForm(i){let b=db.branches[i];openForm('موقع '+b.name,field('خط العرض Latitude (-90 إلى 90)','lat','text',b.lat??'')+field('خط الطول Longitude (-180 إلى 180)','lng','text',b.lng??'')+'<p>انسخ الإحداثيات من دبوس الفرع في Google Maps. النطاق ٨٠ متر ثابت.</p>',f=>{const lat=Number(f.get('lat')),lng=Number(f.get('lng'));if(!Number.isFinite(lat)||Math.abs(lat)>90||!Number.isFinite(lng)||Math.abs(lng)>180)throw new Error('إحداثيات غير صالحة');b.lat=lat;b.lng=lng;audit('تحديث موقع '+b.name)});$('#form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),lat=Number(f.get('lat')),lng=Number(f.get('lng'));if(!String(f.get('lat')).trim()||!String(f.get('lng')).trim()||!Number.isFinite(lat)||Math.abs(lat)>90||!Number.isFinite(lng)||Math.abs(lng)>180)return toast('راجع الإحداثيات: Latitude ±90 وLongitude ±180');b.lat=lat;b.lng=lng;audit('تحديث موقع '+b.name);$('#modal').close();render();toast('تم حفظ موقع الفرع بنطاق ٨٠ متر')}}
function locateBranch(i){if(!navigator.geolocation)return toast('تحديد الموقع غير مدعوم');toast('جارٍ تحديد موقعك؛ لازم تكون داخل الفرع');navigator.geolocation.getCurrentPosition(p=>{if(p.coords.accuracy>30)return toast('دقة الموقع ضعيفة؛ أدخل إحداثيات دبوس الفرع يدويًا');if(!confirm(`هل أنت داخل ${db.branches[i].name}؟ حفظ موقعك الحالي كمركز الفرع بدقة ±${Math.ceil(p.coords.accuracy)} متر؟`))return;db.branches[i].lat=p.coords.latitude;db.branches[i].lng=p.coords.longitude;audit('تحديد موقع '+db.branches[i].name);render()},()=>toast('تعذر الوصول للموقع؛ استخدم إدخال الإحداثيات'),{enableHighAccuracy:true,maximumAge:0,timeout:20000})}
function requestForEmployee(){const s=currentEmployee();if(!s)return;openForm('طلب استثنائي',options('نوع الطلب','type',['إجازة اعتيادية','إجازة مرضية','إذن انصراف مبكر','إذن تأخير وصول','إذن خروج وعودة أثناء الوردية','تصحيح بصمة','تبديل وردية'])+field('التفاصيل والموعد','detail')+'<label>اليوم (اختياري)<input name="day" type="date"></label><label>عدد الساعات (اختياري)<input name="hours" type="number" min="0.5" max="24" step="0.5"></label>',f=>{const r={id:Date.now(),name:s.name,employeeId:s.id,type:f.get('type'),detail:f.get('detail'),status:'معلق'};if(f.get('day'))r.day=f.get('day');if(f.get('hours'))r.hours=Number(f.get('hours'));db.requests.push(r);audit('طلب جديد من '+s.name)})}
function editEmployee(){const s=db.staff.find(s=>s.id==$('#staffAction').value);openForm('تعديل بيانات الموظف',field('الاسم','name','text',s.name)+field('الوظيفة','job','text',s.job)+options('الفرع','branch',db.branches.map(b=>b.name)),f=>{if(db.punches.some(p=>p.employeeId===s.id&&!p.out))return toast('أغلق وردية الموظف قبل تعديل بياناته');Object.assign(s,Object.fromEntries(f));audit('تعديل موظف '+s.name)});$('#fields select').value=s.branch}
render();

function hoursReviewBlock(){const todayC=cairoDay(),openOld=db.punches.filter(p=>!p.out&&cairoDay(p.in)<todayC),openToday=db.punches.filter(p=>!p.out&&cairoDay(p.in)===todayC);return card('مراجعة الساعات — للمتابعة فقط ولا توقف التسجيل',`<p>تسجيل الحضور والانصراف بالـ GPS متاح دائمًا بدون أي موافقة؛ هذه القائمة سجل للمراجعة فقط.</p>${openOld.map(p=>`<div class="request"><div class="details"><strong>${esc(p.name)} <span style="color:#a2aaa4;font-weight:400">/ ${esc(p.branch)}</span></strong><p>سجل حضور يوم ${cairoDay(p.in)} (${stamp(p.in)}) ولم يسجل انصراف حتى الآن</p></div><span class="badge amber">لم يسجل انصراف</span></div>`).join('')||'<p class="empty">لا توجد ورديات قديمة بدون انصراف ✓</p>'}<small>${openToday.length?`ورديات مفتوحة اليوم: ${openToday.length}`:'لا توجد ورديات مفتوحة اليوم'}</small>`)}
